namespace MyApp.Api.Models;

public sealed class TelemetrySample
{
    // Generated by the agent and reused when retrying the same message.
    public Guid Id { get; set; }

    public string DeviceId { get; set; } = "";

    // When the agent measured the values.
    public DateTime RecordedAtUtc { get; set; }

    // When the backend accepted the sample.
    public DateTime ReceivedAtUtc { get; set; } = DateTime.UtcNow;

    public double? CpuTemperatureC { get; set; }
    public double? CpuUsagePercent { get; set; }
    public double? CpuClockMhz { get; set; }

    public long? MemoryUsedBytes { get; set; }
    public long? MemoryTotalBytes { get; set; }

    public double? IntegratedGpuTemperatureC { get; set; }
    public double? IntegratedGpuClockMhz { get; set; }

    public double? NvidiaGpuTemperatureC { get; set; }
    public double? NvidiaGpuUsagePercent { get; set; }
    public double? NvidiaGpuClockMhz { get; set; }

    public long? NvidiaMemoryUsedBytes { get; set; }
    public long? NvidiaMemoryTotalBytes { get; set; }

    public int? CpuFanRpm { get; set; }
    public int? GpuFanRpm { get; set; }

    public double? SsdTemperatureC { get; set; }
}
